SourceCode.Declaration:
/// <summary>
/// Data contract for the <c>UTCSFCustomerPushBatchService</c> SysOperation batch job.
/// </summary>
[DataContractAttribute]
public class UTCSFCustomerPushBatchContract implements SysOperationValidatable, SysOperationInitializable
{
    private int     maxRecordsToProcess;
    private int     batchSizePerApiCall;
    private boolean includeFailedForRetry;

}

Method.Source:
public void initialize()
{
    maxRecordsToProcess   = 500;
    batchSizePerApiCall   = 1;
    includeFailedForRetry = false;
}

[DataMemberAttribute('MaxRecordsToProcess'),
 SysOperationLabelAttribute(literalStr('Max Queue Records Per Run')),
 SysOperationHelpTextAttribute(literalStr('Maximum number of pending queue records to process in a single batch execution.')),
 SysOperationDisplayOrderAttribute('1')]
public int parmMaxRecordsToProcess(int _maxRecordsToProcess = maxRecordsToProcess)
{
    maxRecordsToProcess = _maxRecordsToProcess;
    return maxRecordsToProcess;
}

[DataMemberAttribute('BatchSizePerApiCall'),
 SysOperationLabelAttribute(literalStr('Customers Per API Call')),
 SysOperationHelpTextAttribute(literalStr('1 customer per call for real-time triggers; up to 200 per call for bulk backfills.')),
 SysOperationDisplayOrderAttribute('2')]
public int parmBatchSizePerApiCall(int _batchSizePerApiCall = batchSizePerApiCall)
{
    batchSizePerApiCall = _batchSizePerApiCall;
    return batchSizePerApiCall;
}

[DataMemberAttribute('IncludeFailedForRetry'),
 SysOperationLabelAttribute(literalStr('Re-queue Failed Records')),
 SysOperationHelpTextAttribute(literalStr('If enabled, resets Failed records (excluding HTTP 400 validation errors) to Pending before processing.')),
 SysOperationDisplayOrderAttribute('3')]
public boolean parmIncludeFailedForRetry(boolean _includeFailedForRetry = includeFailedForRetry)
{
    includeFailedForRetry = _includeFailedForRetry;
    return includeFailedForRetry;
}

public boolean validate()
{
    boolean isValid = true;

    if (batchSizePerApiCall < 1 || batchSizePerApiCall > 200)
    {
        isValid = checkFailed('Customers Per API Call must be between 1 and 200.');
    }

    if (maxRecordsToProcess < 1)
    {
        isValid = checkFailed('Max Queue Records Per Run must be at least 1.');
    }

    return isValid;
}
